{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdは「生活保護の費用は、国と自治体でどう分担しているのか。」ですが、hsは「学校の教科書や給食のお金を出すのが大変な家には、どんな手助けがあるのでしょう？」と全く別の内容（就学援助など）になっています。",
      "fix": "「生活保護にかかる費用は、国と地方自治体でどのように分担しているのでしょうか。」のように書き直す。"
    },
    {
      "type": "ふりがなの読み",
      "where": "summary の es",
      "detail": "「おおよその数《すう》」となっていますが、「おおよその」に続く「数」の読みは「かず」が自然です。",
      "fix": "「おおよその数《かず》」にする。"
    }
  ]
}
